CREATE TABLE security_companies(id text PRIMARY KEY,name text NOT NULL,status text NOT NULL CHECK(status IN ('active','disabled')),operational_enabled boolean NOT NULL DEFAULT false,version integer NOT NULL DEFAULT 1 CHECK(version>0));
CREATE TABLE security_profiles(company_id text NOT NULL REFERENCES security_companies(id),id text NOT NULL,name text NOT NULL,description text NOT NULL DEFAULT '',system_key text,protected boolean NOT NULL DEFAULT false,status text NOT NULL DEFAULT 'active' CHECK(status IN ('active','retired')),scope text NOT NULL CHECK(scope IN ('company','assigned')),grants jsonb NOT NULL CHECK(jsonb_typeof(grants)='array'),revision integer NOT NULL DEFAULT 1 CHECK(revision>0),PRIMARY KEY(company_id,id),UNIQUE(company_id,system_key));
CREATE UNIQUE INDEX security_profile_names ON security_profiles(company_id,lower(name));
CREATE TABLE security_memberships(company_id text NOT NULL REFERENCES security_companies(id),subject_id text NOT NULL,status text NOT NULL CHECK(status IN ('active','disabled')),revision integer NOT NULL DEFAULT 1,PRIMARY KEY(company_id,subject_id));
CREATE TABLE security_assignments(company_id text NOT NULL,subject_id text NOT NULL,profile_id text NOT NULL,PRIMARY KEY(company_id,subject_id,profile_id),FOREIGN KEY(company_id,subject_id) REFERENCES security_memberships(company_id,subject_id),FOREIGN KEY(company_id,profile_id) REFERENCES security_profiles(company_id,id));
CREATE INDEX security_assignments_profile ON security_assignments(company_id,profile_id);
CREATE TABLE security_audit(id bigserial PRIMARY KEY,company_id text NOT NULL REFERENCES security_companies(id),actor text NOT NULL,entity text NOT NULL,entity_id text NOT NULL,before_value jsonb,after_value jsonb,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX security_audit_company ON security_audit(company_id,id);
